describe("Sphinx scoring", () => {
  it.todo("scores an army without a Sphinx as 0 — Chimera, Orthrus, Zombie → 0");
  it.todo("scores a lone Sphinx with one other type as 2 — Sphinx, Cyclops → 2");
  it.todo("scores a Sphinx with two other types as 2 — Sphinx, Chimera, Orthrus → 2");
  it.todo("counts several cards of the same monster as one type — Sphinx, Chimera, Chimera, Chimera, Orthrus, Orthrus → 2");
  it.todo("counts all three Undead Warrior variants as a single type — Sphinx, Undead Warrior (1), Undead Warrior (3), Chimera → 2");
  it.todo("does not count the scoring Sphinx itself as a type — Sphinx, Chimera, Orthrus, Zombie, Hydra → 3");
  it.todo("scores 2 per type beyond three — Sphinx, Chimera, Orthrus, Zombie, Hydra, Cyclops → 5");
  it.todo("counts Undead Warrior variants as one type beyond three — Sphinx, Undead Warrior (1), Undead Warrior (2), Undead Warrior (3), Cyclops, Orthrus, Chimera → 3");
  it.todo("lets each Sphinx count the other Sphinx as a type — Sphinx, Sphinx, Chimera, Orthrus → 4");
  it.todo("scores both Sphinxes beyond three types — Sphinx, Sphinx, Chimera, Orthrus, Zombie → 6");
});

