const MANY_TYPES_THRESHOLD = 3;

export function scoreArmy(army: Card[]): number {
  const sphinxes = army.filter((card) => card.monster === SPHINX);
  if (sphinxes.length === 0) return 0;

  const otherTypes = new Set(
    army.filter((card) => card.monster !== SPHINX).map((card) => card.monster),
  );
  if (otherTypes.size > MANY_TYPES_THRESHOLD) return BASE_POINTS + 2;
  return BASE_POINTS + FEW_TYPES_BONUS;
}

