export type Card = {
  monster: string;
  rank?: number;
};

const SPHINX = "sphinx";

/** "Sphinx — 1 point. … else 1." */
const BASE_POINTS = 1;
const FEW_TYPES_BONUS = 1;

export function scoreArmy(army: Card[]): number {
  const sphinxes = army.filter((card) => card.monster === SPHINX);
  return sphinxes.length === 0 ? 0 : BASE_POINTS + FEW_TYPES_BONUS;
}

export type Card = {
  monster: string;
