export type Card = {
  monster: string;
  rank?: number;
};

const SPHINX = "sphinx";

/** "Sphinx — 1 point. … else 1." */
const BASE_POINTS = 1;
const FEW_TYPES_BONUS = 1;

const MANY_TYPES_THRESHOLD = 3;
const POINTS_PER_EXTRA_TYPE = 2;

const isSphinx = (card: Card) => card.monster === SPHINX;

/** The distinct monster types a Sphinx sees — it does not count itself. */
function typesSeenBySphinx(army: Card[]): number {
  return new Set(army.filter((card) => !isSphinx(card)).map((c) => c.monster))
    .size;
}

/** "2 per type beyond three, else 1." */
function bonusForTypes(types: number): number {
  if (types <= MANY_TYPES_THRESHOLD) return FEW_TYPES_BONUS;
  return POINTS_PER_EXTRA_TYPE * (types - MANY_TYPES_THRESHOLD);
}

export function scoreArmy(army: Card[]): number {
  if (!army.some(isSphinx)) return 0;
  return BASE_POINTS + bonusForTypes(typesSeenBySphinx(army));
}

